<script setup>
import Card from 'primevue/card'
import Button from 'primevue/button'
import Tag from 'primevue/tag'
import Image from 'primevue/image'
import { computed } from 'vue'

const props = defineProps({
  article: { type: Object, required: true }
})
const emit = defineEmits(['toggle-publish', 'delete'])

const statusSeverity = computed(() => props.article.isPublished ? 'success' : 'danger')
const statusText = computed(() => props.article.isPublished ? 'Опубликовано' : 'Черновик')

const placeholderImage = 'data:image/jpeg;base64,'
</script>

<template>
  <Card class="article-card">
    <template #header>
      <Image :src="article.image || placeholderImage" alt="Обложка статьи" width="100%" />
    </template>
    <template #title>
      <div class="card-title">
        <span>{{ article.title }}</span>
        <Tag :severity="statusSeverity" :value="statusText" />
      </div>
    </template>
    <template #subtitle>Автор: {{ article.author }}</template>
    <template #content>
      <p>{{ article.body }}</p>
    </template>
    <template #footer>
      <div class="card-actions">
        <Button 
          :label="article.isPublished ? 'Снять' : 'Опубликовать'"
          :icon="article.isPublished ? 'pi pi-eye-slash' : 'pi pi-eye'"
          severity="secondary"
          size="small"
          @click="emit('toggle-publish', article.id)"
        />
        <Button icon="pi pi-trash" severity="danger" text rounded @click="emit('delete', article.id)" aria-label="Удалить" />
      </div>
    </template>
  </Card>
</template>

<style scoped>
.article-card {
  height: 100%;
  display: flex;
  flex-direction: column;
}
.card-title {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 10px;
}
.card-actions {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: auto;
}
</style>